#!/usr/bin/env python3
"""Generate a fixed-address linker script for ro9.

Each function's .text is placed at its exact VRAM, so:
  * a C object shorter than its slot leaves a zero-filled gap (no padding hack),
  * call relocations resolve to the right absolute addresses,
  * object order in the link no longer matters.
"""
import glob, os, re, sys

ROOT = sys.argv[1] if len(sys.argv) > 1 else "/home/user/sfzfg/roundtrip"
ASM = f"{ROOT}/ro9"
OUT = f"{ROOT}/ro9_fixed.ld"

TEXT_BASE = 0x1F0080
DATA_ADDR = 0x5AF580
DATA_SIZE = 0x5B8E80

lines = [
    "/* generated by tools/roundtrip/gen_ld.py - fixed-address ro9 layout */",
    "SECTIONS",
    "{",
    "  . = 0x1F0000;",
    "  .header 0x1F0000 : { build_eabi/header.o(.rodata) }",
]

funcs = []
for s in sorted(glob.glob(f"{ASM}/func_*.s")):
    stem = os.path.basename(s)[:-2]
    va = int(stem[5:], 16)
    funcs.append((va, stem))
funcs.sort()

for va, stem in funcs:
    lines.append(f"  .text 0x{va:08X} : {{ build_eabi/{stem}.o(.text) }}")

lines += [
    f"  .data 0x{DATA_ADDR:08X} : {{ build_eabi/data.o(.data) }}",
    "  /DISCARD/ : { *(*) }",
    "}",
    "",
]
open(OUT, "w").write("\n".join(lines))
print(f"wrote {OUT}: {len(funcs)} function placements")
